using System.Security.Claims;using CampusPlacementManagement.Data;using CampusPlacementManagement.DTOs.PlacementTracking;using CampusPlacementManagement.Models.Enums;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace CampusPlacementManagement.Controllers;
[ApiController,Route("api/reports"),Authorize]
public class PlacementTrackingController:ControllerBase
{private readonly ApplicationDbContext _db;public PlacementTrackingController(ApplicationDbContext db)=>_db=db;private string Uid()=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
[Authorize(Roles="SuperAdmin"),HttpGet("platform-overview")]public async Task<PlacementOverviewDto> Platform(){var total=await _db.Students.CountAsync();var apps=await _db.JobApplications.CountAsync();var selected=await _db.JobApplications.CountAsync(x=>x.Status==ApplicationStatus.Selected);return Calc(total,apps,selected);}
[Authorize(Roles="PlacementOfficer"),HttpGet("college-overview")][HttpGet("student-placement")]public async Task<PlacementOverviewDto> College(){var o=await _db.PlacementOfficers.FirstAsync(x=>x.UserId==Uid());var total=await _db.Students.CountAsync(x=>x.CollegeId==o.CollegeId);var apps=await _db.JobApplications.CountAsync(x=>x.Student.CollegeId==o.CollegeId);var selected=await _db.JobApplications.CountAsync(x=>x.Student.CollegeId==o.CollegeId&&x.Status==ApplicationStatus.Selected);return Calc(total,apps,selected);}
[Authorize(Roles="CompanyHR"),HttpGet("company-recruitment")]public async Task<IActionResult> Company(){var hr=await _db.CompanyHRs.FirstAsync(x=>x.UserId==Uid());var jobs=await _db.Jobs.Where(x=>x.CreatedByHRId==hr.CompanyHRId).Select(x=>new{x.JobId,x.JobTitle,Applications=x.Applications.Count,Selected=x.Applications.Count(a=>a.Status==ApplicationStatus.Selected)}).ToListAsync();return Ok(jobs);}
private static PlacementOverviewDto Calc(int total,int apps,int selected)=>new(){TotalStudents=total,TotalApplications=apps,TotalSelected=selected,PlacementPercentage=total==0?0:Math.Round(selected*100m/total,2)};}
